1	import type {AddressInfo} from 'node:net';
2	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
3	import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
4	import {setLogger} from '../shared/logger.js';
5	import {connectClient, delegatingTo, MALFORMED_LIST_SESSIONS, startEngineWith, stopEngines} from './wsTestSupport.js';
6	
7	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
8	
9	interface Frame {
10	  type: string;
11	  sessionId?: string;
12	  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
13	  code?: string;
14	  message?: string;
15	}
16	
17	const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
18	
19	beforeEach(() => {
20	  logLines.length = 0;
21	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
22	    void logLines.push({level, category, message, fields});
23	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
24	});
25	
26	afterEach(async () => {
27	  await stopEngines();
28	  setLogger();
29	});
30	
31	const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
32	  const {hal} = await startEngineWith({sessionStore: store, wsAuth: async () => ({id: userId})});
33	  const {port} = hal.server.address() as AddressInfo;
34	  return `ws://127.0.0.1:${port}/hal/ws`;
35	};
36	
37	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
38	  const client = connectClient(url);
39	  const frames: Frame[] = [];
40	  let connected: Frame = {type: ''};
41	  await new Promise<void>(resolve => {
42	    client.on('message', raw => {
43	      const frame = JSON.parse(String(raw)) as Frame;
44	      if (frame.type !== 'connected') {
45	        if (frame.type === 'pong') resolve();
46	        else frames.push(frame);
47	        return;
48	      }
49	      connected = frame;
50	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
51	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
52	    });
53	  });
54	  return {connected, frames};
55	};
56	
57	describe('listing conversations over the WebSocket protocol', () => {
58	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
59	    const inner = new InMemorySessionStore();
60	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
61	    const summaries: SessionSummary[] = [
62	      {
63	        sessionId: 's2',
64	        createdAt: new Date('2026-01-01T00:00:00.000Z'),
65	        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
66	        entryCount: 4,
67	      },
68	    ];
69	    const store: SessionStore = {
70	      ...delegatingTo(inner),
71	      listFor: (userId, options) => {
72	        seen.push({userId, options});
73	        return summaries;
74	      },
75	    };
76	    const url = await startEngine(store, 'u1');
77	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
78	
79	    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
80	
