1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
6	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
55	    }
56	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
57	    return wsErrorHandler(ws, async () => answerFrame(ws, session, sessionStore, validation));
58	  };
59	}
60	
61	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
62	async function answerInTurn(
63	  ws: WebSocket,
64	  session: ChatSession,
65	  orchestrator: ChatOrchestrator,
66	  validation: ValidationResult,
67	  signal: AbortSignal | undefined
68	): Promise<void> {
69	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
70	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
71	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
72	    return;
73	  }
74	  const startedAt = Date.now();
75	  try {
76	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
77	  } finally {
78	    endTurn(ws, session, signal, startedAt);
79	  }
80	}
81	
82	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
83	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
84	  if (signal?.aborted) {
85	    log.info('message', 'turn abandoned: its socket closed', {
86	      sessionId: session.sessionId,
87	      elapsedMs: Date.now() - startedAt,
88	    });
89	    return;
90	  }
91	  sendStreamEnd(ws);
92	}
93	
94	async function answerUserMessage(
95	  ws: WebSocket,
96	  session: ChatSession,
97	  orchestrator: ChatOrchestrator,
98	  validation: ValidationResult,
99	  signal: AbortSignal | undefined
100	): Promise<void> {
101	  const message = validation.valid ? validation.data : undefined;
102	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
103	  // No store here: a frame inside the lock is a turn, and a turn is never answered with a list.
104	  await answerFrame(ws, session, undefined, validation);
105	}
106	
107	async function answerFrame(
108	  ws: WebSocket,
109	  session: ChatSession,
110	  sessionStore: SessionStore | undefined,
111	  validation: ValidationResult
112	): Promise<void> {
113	  if (!validation.valid) {
114	    log.warn('message', 'validation failed', {error: validation.error});
115	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
116	    return;
117	  }
118	
119	  const message = validation.data;
120	  if (message.type === 'ping') return handlePing(ws, message.timestamp);
121	  if (message.type === 'list_sessions') return answerListSessions(ws, session, sessionStore, message);
122	}
123	
124	// Off the per-session lock, beside ping: a history request is not a turn, it mutates nothing, and one queued behind a streaming answer would look broken.
125	async function answerListSessions(
126	  ws: WebSocket,
127	  session: ChatSession,
128	  sessionStore: SessionStore | undefined,
129	  message: ListSessionsMessage
130	): Promise<void> {
131	  try {
132	    // The id is the connection's, read here and never from the frame, so a client can list only its own conversations.
133	    const summaries =
134	      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
135	    sendSessionList(ws, summaries.map(toWireSummary));
136	  } catch (error) {
137	    const detail = error instanceof Error ? error.message : String(error);
138	    // The store's message goes to the log, not the wire: the client renders it, and it names the database.
139	    log.error('ws', 'conversation list failed', {userId: session.userId, error: detail});
140	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
141	  }
142	}
143	
144	// A Date does not survive JSON.stringify as a Date, and the protocol types describe what goes on the wire.
145	const toWireSummary = (summary: SessionSummary): SessionSummaryFrame => ({
146	  sessionId: summary.sessionId,
147	  createdAt: summary.createdAt.toISOString(),
148	  updatedAt: summary.updatedAt.toISOString(),
149	  entryCount: summary.entryCount,
150	});
151	
152	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
153	function isUserMessageFrame(rawMessage: unknown): boolean {
154	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
155	}
156	
157	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
158	  try {
159	    await action();
160	  } catch (error) {
161	    const message = error instanceof Error ? error.message : 'Unknown error';
162	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
163	    log.error('message', 'handling error', {error: message, code});
164	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
165	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
166	      return;
167	    }
168	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
169	  }
170	}
171	
172	async function handleUserMessage(
173	  ws: WebSocket,
174	  session: ChatSession,
175	  orchestrator: ChatOrchestrator,
176	  content: string,
177	  signal: AbortSignal | undefined
178	): Promise<void> {
179	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
180	
181	  const userEntry = createUserEntry(content);
182	  const userIndex = appendEntry(session, userEntry);
183	  sendUpsert(ws, userIndex, userEntry);
184	
185	  const parser = new ThinkingTagParser();
186	  const state: StreamState = {
187	    thinkingIndex: null,
188	    assistantIndex: null,
189	    suppressOutput: false,
190	    sentAssistantIndices: [],
191	  };
192	
193	  let textChunkCount = 0;
194	
195	  try {
196	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
197	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
198	      if (signal?.aborted) break;
199	      textChunkCount = logChunk(chunk, textChunkCount);
200	      processChunk(ws, session, state, parser, chunk);
201	    }
202	  } finally {
203	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
204	    flushHeldText(ws, session, state, parser);
205	    closeCutOff(ws, session, state, 'thinkingIndex');
206	    closeCutOff(ws, session, state, 'assistantIndex');
207	  }
208	
209	  if (textChunkCount > 0) {
210	    log.debug('stream', `received ${textChunkCount} text chunks`);
211	  }
212	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
213	}
214	
215	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
216	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
217	  if (chunk.type === 'text') return textChunkCount + 1;
218	
219	  if (textChunkCount > 0) {
220	    log.debug('stream', `received ${textChunkCount} text chunks`);
221	  }
222	
223	  if (chunk.type === 'tool_result') {
224	    log.debug('stream', 'tool_result chunk', {
225	      messageCount: chunk.clientMessages.length,
226	      types: chunk.clientMessages.map(m => m.type),
227	    });
228	    return 0;
229	  }
230	
231	  log.debug('stream', 'chunk', {type: chunk.type});
232	  return 0;
233	}
234	
235	function processChunk(
236	  ws: WebSocket,
237	  session: ChatSession,
238	  state: StreamState,
239	  parser: ThinkingTagParser,
240	  chunk: MessageChunk
241	): void {
242	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
243	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
244	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
245	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
246	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
247	}
248	
249	function processTextChunk(
250	  ws: WebSocket,
251	  session: ChatSession,
252	  state: StreamState,
253	  parser: ThinkingTagParser,
254	  text: string
255	): void {
256	  const segments = parser.push(text);
257	  for (const segment of segments) {
258	    handleTextSegment(ws, session, state, segment);
259	  }
260	}
261	
262	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
263	  if (segment.type === 'thinking') {
264	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
265	    return;
266	  }
267	  commitAndClear(ws, session, state, 'thinkingIndex');
268	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
269	}
270	
271	function streamSegment(
272	  ws: WebSocket,
273	  session: ChatSession,
274	  state: StreamState,
275	  key: StateIndexKey,
276	  createEntry: EntryFactory,
277	  content: string
278	): void {
279	  const isNew = initSegment(session, state, key, createEntry);
280	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
281	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
282	  appendDelta(session, state[key]!, content);
283	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
284	}
285	
286	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
287	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
288	  markSuppressed(session, index);
289	  sendSkip(ws, index);
290	}
291	
292	function markSuppressed(session: ChatSession, index: number): void {
293	  const entry = session.entries[index];
294	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
295	}
296	
297	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
298	  if (state[key] !== null) return false;
299	  state[key] = appendEntry(session, createEntry());
300	  return true;
301	}
302	
303	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
304	  const index = state[key];
305	  if (index === null) return;
306	
307	  commitEntry(session, index);
308	  state[key] = null;
309	
310	  // Only what the client received can be retracted, and only assistant entries.
311	  if (state.suppressOutput) return;
312	
313	  sendCommit(ws, index);
314	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
315	}
316	
317	function processToolUseChunk(
318	  ws: WebSocket,
319	  session: ChatSession,
320	  toolCall: {name: string; input: Record<string, unknown>}
321	): void {
322	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
323	  const toolIndex = appendEntry(session, toolEntry);
324	  sendUpsert(ws, toolIndex, toolEntry);
325	}
326	
327	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
328	  for (const msg of clientMessages) {
329	    log.debug('stream', 'forwarding client message to frontend', {
330	      type: msg.type,
331	      index: 'index' in msg ? msg.index : undefined,
332	    });
333	    sendJson(ws, msg);
334	  }
335	}
336	
337	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
338	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
339	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
340	  commitOpenEntries(ws, session, state);
341	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
342	
343	  for (const idx of state.sentAssistantIndices) {
344	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
345	    markSuppressed(session, idx);
346	  }
347	
348	  state.sentAssistantIndices = [];
349	  state.suppressOutput = true;
350	}
351	
352	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
353	  flushHeldText(ws, session, state, parser);
354	  commitOpenEntries(ws, session, state);
355	}
356	
357	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
358	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
359	  for (const segment of parser.flush()) {
360	    handleTextSegment(ws, session, state, segment);
361	  }
362	}
363	
364	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
365	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
366	  const index = state[key];
367	  if (index === null) return;
368	  markTruncated(session, index);
369	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
370	  commitAndClear(ws, session, state, key);
371	}
372	
373	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
374	  commitAndClear(ws, session, state, 'thinkingIndex');
375	  commitAndClear(ws, session, state, 'assistantIndex');
