670	    yield text(`answer ${run}`);
671	    await gates[run].until;
672	    yield STOP;
673	  };
674	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
675	  const handle = createMessageHandler({processMessageStream} as unknown as ChatOrchestrator);
676	
677	  return {
678	    session,
679	    handed,
680	    release: (run: number) => gates[run].release(),
681	    close: () => {
682	      socket.readyState = WebSocket.CLOSED;
683	    },
684	    frames: () => wire(sent),
685	    send: (raw: unknown) => handle(ws, session, raw),
